// Concatena transcrição do TLDV - Versão Ajustada
// Input: Webhook payload do TLDV
// Output: String com transcrição formatada

const input = $input.first().json;

// O payload é um array, pega o primeiro elemento
const payload = Array.isArray(input) ? input[0] : input;

// Acessa o array de transcrições
const transcriptData = payload?.data;

// Valida se existem dados
if (!transcriptData || !Array.isArray(transcriptData)) {
  return [{
    json: {
      meetingId: null,
      transcriptId: null,
      executedAt: new Date().toISOString(),
      totalFalas: 0,
      transcricao: ""
    }
  }];
}

// Concatena as falas
let transcricao = "";
transcriptData.forEach(entry => {
  const speaker = entry.speaker || "Desconhecido";
  const text = entry.text || "";

  transcricao += `${speaker}: ${text}\n`;
});

// Remove última quebra de linha
transcricao = transcricao.trim();

// Retorna resultado
return [{
  json: {
    meetingId: payload.meetingId || null,
    transcriptId: payload.id || null,
    executedAt: new Date().toISOString(),
    totalFalas: transcriptData.length,
    transcricao: transcricao
  }
}];
